head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[accordion > P > accessibility]<br/>Accordion 컴포넌트에 웹접근성 지원 기능을 일괄적으로 적용할지 설정합니다.",
    "validation" : [
        "enterKeyPanelToggle=false 이면 accessibility=true 여도 Enter 키로 패널을 토글할 수 없습니다.",
        "disabledPanels=true 인 패널에서는 accessibility 속성값과 관계없이 패널 열기/닫기가 차단됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        accessibility : con_accessibility.getText(),
        enterKeyPanelToggle : con_enterKeyPanelToggle.getText(),
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onpanelload", "onpanelunload"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="* 시나리오1 : enterKeyPanelToggle=false 상태에서 panelTitle 포커스 후 Enter 키로 토글 시도"', '', 'label1');
    $c.gcm.createLabel('label="* 시나리오2 : panels3 은 disabledPanels=true 상태이며 클릭/Enter 모두 차단되는지 확인"', '', 'label2');

    strTarget += '<w2:accordion ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:240px; height:320px;">';
    strTarget += '<w2:panels style="" id="panels1" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle1" label="panelTitle1"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent1">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel1"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels2" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle2" label="panelTitle2"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent2">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel2"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels3" class="" disabledPanels="true">';
    strTarget += '<w2:panelTitle style="" id="panelTitle3" label="panelTitle3 (disabled)"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent3">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel3"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '</w2:accordion>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "accordion",
        strTarget,
        grp_comp
    );
}



// onpanelload (panelID, userID)
scwin.target1_onpanelload = function (panelID, userID) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onpanelload=====");
    wf_body_bottom.getObj("scwin").setReturnValue("panelID : " + panelID);
    wf_body_bottom.getObj("scwin").setReturnValue("userID : " + userID);
};



// onpanelunload (panelID, userID)
scwin.target1_onpanelunload = function (panelID, userID) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onpanelunload=====");
    wf_body_bottom.getObj("scwin").setReturnValue("panelID : " + panelID);
    wf_body_bottom.getObj("scwin").setReturnValue("userID : " + userID);
};



// 특정 패널 타이틀에 포커스 (Enter 키 동작 확인용)
scwin.btn_focusTitle1_onclick = function (e) {
    let titleEl = document.querySelector("#panelTitle1_title");
    if (titleEl) {
        titleEl.focus();
        wf_body_bottom.getObj("scwin").setReturnValue("panelTitle1_title 포커스 처리됨");
    }
};



// 현재 열린 패널 정보 출력
scwin.btn_getOpenPanel_onclick = function (e) {
    let info = target1.getOpenPanelInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("getOpenPanelInfo : " + (info ? info.id : "null"));
};
